<template>
  <div class="app-container home-content-page">
    <template v-if="viewMode === 'list'">
      <section class="page-heading">
        <div><p class="eyebrow">MALL OPERATIONS / PAGE CONTENT</p><h1>首页内容运营</h1><p>主视觉、公告条和推荐专区独立保存与排期，发布前可进入工作台预览。</p></div>
        <el-button v-hasPermi="['mall:content:add']" type="primary" icon="el-icon-plus" @click="openCreate">新建内容</el-button>
      </section>
      <el-form ref="queryForm" :model="query" :inline="true" size="small" class="query-form">
        <el-form-item label="内容名称" prop="keyword"><el-input v-model="query.keyword" clearable placeholder="搜索内容名称" @keyup.enter.native="handleQuery" /></el-form-item>
        <el-form-item label="内容类型" prop="contentType"><el-select v-model="query.contentType" clearable placeholder="全部类型"><el-option v-for="item in contentTypes" :key="item.value" :label="item.label" :value="item.value" /></el-select></el-form-item>
        <el-form-item label="发布状态" prop="status"><el-select v-model="query.status" clearable placeholder="全部状态"><el-option label="草稿" value="DRAFT" /><el-option label="已发布" value="PUBLISHED" /><el-option label="已停用" value="DISABLED" /></el-select></el-form-item>
        <el-form-item><el-button type="primary" icon="el-icon-search" @click="handleQuery">查询</el-button><el-button icon="el-icon-refresh" @click="resetQuery">重置</el-button></el-form-item>
      </el-form>
      <section class="summary-band"><div><span>当前页内容</span><strong>{{ rows.length }}</strong></div><div><span>线上生效</span><strong>{{ countStatus('ONLINE') }}</strong></div><div><span>待生效排期</span><strong>{{ countStatus('SCHEDULED') }}</strong></div><div><span>草稿</span><strong>{{ countStatus('DRAFT') }}</strong></div></section>
      <el-table v-loading="loading" :data="rows" border>
        <el-table-column label="内容" min-width="220" fixed="left"><template slot-scope="scope"><strong>{{ scope.row.contentName }}</strong><small>#{{ scope.row.contentId }}</small></template></el-table-column>
        <el-table-column label="类型" width="110"><template slot-scope="scope">{{ typeLabel(scope.row.contentType) }}</template></el-table-column>
        <el-table-column label="状态" width="110"><template slot-scope="scope"><el-tag size="mini" :type="statusType(scope.row.runtimeStatus)">{{ runtimeLabel(scope.row.runtimeStatus) }}</el-tag></template></el-table-column>
        <el-table-column prop="effectiveTime" label="生效时间" width="165" /><el-table-column label="下线时间" width="165"><template slot-scope="scope">{{ scope.row.expireTime || '不设定' }}</template></el-table-column><el-table-column label="更新人" width="120"><template slot-scope="scope">{{ scope.row.updateBy || scope.row.createBy || '-' }}</template></el-table-column>
        <el-table-column label="操作" width="210" fixed="right"><template slot-scope="scope"><el-button v-hasPermi="['mall:content:query']" type="text" icon="el-icon-view" @click="openEditor(scope.row.contentId, true)">预览</el-button><el-button v-hasPermi="['mall:content:edit']" type="text" icon="el-icon-edit" @click="openEditor(scope.row.contentId, false)">编辑</el-button><el-button v-if="scope.row.status !== 'DISABLED'" v-hasPermi="['mall:content:disable']" type="text" class="danger-link" icon="el-icon-circle-close" @click="handleDisable(scope.row)">停用</el-button></template></el-table-column>
      </el-table>
      <pagination v-show="total > 0" :total="total" :page.sync="query.pageNum" :limit.sync="query.pageSize" @pagination="load" />
    </template>

    <template v-else>
      <section class="page-heading"><div><p class="eyebrow">EDITOR &amp; LIVE PREVIEW</p><h1>{{ form.contentId ? '编辑首页内容' : '新建首页内容' }}</h1><p>采用固定 C1+ 首页模板，编辑内容不会改变首页区块顺序。</p></div><el-button icon="el-icon-back" @click="backToList">返回内容清单</el-button></section>
      <div class="workspace-grid">
        <section class="editor-panel"><header><div><p class="eyebrow">CONTENT</p><h2>内容配置</h2></div><el-tag v-if="previewOnly" type="info">预览模式</el-tag></header>
          <el-form ref="contentForm" :model="form" :rules="rules" label-position="top" size="small" :disabled="previewOnly">
            <el-form-item label="内容类型" prop="contentType"><el-radio-group v-model="form.contentType"><el-radio-button v-for="item in contentTypes" :key="item.value" :label="item.value">{{ item.label }}</el-radio-button></el-radio-group></el-form-item>
            <el-form-item label="内容名称" prop="contentName"><el-input v-model="form.contentName" maxlength="120" show-word-limit /></el-form-item>
            <div class="form-row"><el-form-item label="生效时间" prop="effectiveTime"><el-date-picker v-model="form.effectiveTime" type="datetime" value-format="yyyy-MM-dd'T'HH:mm:ss" placeholder="选择生效时间" /></el-form-item><el-form-item label="下线时间"><el-date-picker v-model="form.expireTime" type="datetime" value-format="yyyy-MM-dd'T'HH:mm:ss" placeholder="可不设定" /></el-form-item></div>
            <template v-if="form.contentType === 'HERO'">
              <el-form-item label="眉题"><el-input v-model="form.heroEyebrow" maxlength="80" /></el-form-item><el-form-item label="主标题" prop="heroTitle"><el-input v-model="form.heroTitle" maxlength="200" /></el-form-item><el-form-item label="辅助文案"><el-input v-model="form.heroSubtitle" type="textarea" :rows="3" maxlength="500" show-word-limit /></el-form-item>
              <div class="form-row"><el-form-item label="按钮文字"><el-input v-model="form.heroActionText" maxlength="40" /></el-form-item><el-form-item label="跳转目标"><el-input v-model="form.heroTargetValue" placeholder="/catalog 或 /product/6" /></el-form-item></div>
              <div class="form-row"><el-form-item label="主图" prop="heroPrimaryImage"><image-upload v-model="form.heroPrimaryImage" :limit="1" :file-size="5" :file-type="['jpg','jpeg','png','webp']" /></el-form-item><el-form-item label="副图" prop="heroSecondaryImage"><image-upload v-model="form.heroSecondaryImage" :limit="1" :file-size="5" :file-type="['jpg','jpeg','png','webp']" /></el-form-item></div>
              <el-form-item label="上新件数"><el-input-number v-model="form.heroNewItemCount" :min="0" :max="999" /></el-form-item>
            </template>
            <template v-else-if="form.contentType === 'TICKER'">
              <div class="ticker-title"><span>公告内容（1 至 5 组）</span><el-button v-if="!previewOnly" type="text" icon="el-icon-plus" :disabled="form.tickerItems.length >= 5" @click="addTicker">添加一组</el-button></div>
              <div v-for="(item, index) in form.tickerItems" :key="index" class="ticker-row"><el-input v-model="item.label" maxlength="80" placeholder="英文标签" /><el-input v-model="item.text" maxlength="200" placeholder="公告内容" /><el-button v-if="!previewOnly" type="text" class="danger-link" :disabled="form.tickerItems.length <= 1" @click="removeTicker(index)">删除</el-button></div>
            </template>
            <template v-else><div class="form-row"><el-form-item label="栏目眉题"><el-input v-model="form.recommendationKicker" maxlength="80" /></el-form-item><el-form-item label="栏目标题"><el-input v-model="form.recommendationTitle" maxlength="120" /></el-form-item></div><el-form-item label="人工优先商品 SPU 编号"><el-input v-model="recommendationInput" placeholder="多个编号使用英文逗号分隔，例如 2,3,8,7" /></el-form-item><div class="form-row"><el-form-item label="展示数量"><el-input-number v-model="form.recommendationDisplayCount" :min="1" :max="8" /></el-form-item><el-form-item label="失效补位"><el-select v-model="form.recommendationFallbackMode"><el-option label="按销量自动补位" value="SALES" /></el-select></el-form-item></div></template>
            <div v-if="!previewOnly" class="editor-actions"><el-button v-hasPermi="[form.contentId ? 'mall:content:edit' : 'mall:content:add']" :loading="saving" @click="submit('DRAFT')">保存草稿</el-button><el-button v-hasPermi="['mall:content:publish']" type="primary" :loading="saving" @click="submit('PUBLISHED')">发布排期</el-button></div>
          </el-form>
        </section>
        <section class="preview-panel"><header><div><p class="eyebrow">LIVE PREVIEW</p><h2>商城首页预览</h2></div><el-radio-group v-model="previewDevice" size="mini"><el-radio-button label="desktop">桌面端</el-radio-button><el-radio-button label="mobile">移动端</el-radio-button></el-radio-group></header>
          <div :class="['store-preview', previewDevice]"><div class="preview-top"><b>日常商店</b><span>首页　全部商品　我的订单　个人中心</span></div><div class="preview-hero"><div><small>{{ form.heroEyebrow || 'NEW DROP' }}</small><h3>{{ form.heroTitle || '今天，也要挑点喜欢的。' }}</h3><p>{{ form.heroSubtitle || '好看、好用，还能让普通一天有一点新鲜。' }}</p><button>{{ form.heroActionText || '开始逛逛' }}</button></div><div class="preview-collage"><img :src="imageUrl(form.heroPrimaryImage)" alt="主图预览"><img :src="imageUrl(form.heroSecondaryImage)" alt="副图预览"><b>{{ form.heroNewItemCount || 8 }} 件</b></div></div><div class="preview-ticker"><template v-for="(item,index) in previewTickers"><span :key="'l'+index">{{ item.label }}</span><b :key="'t'+index">{{ item.text }}</b></template></div><div class="preview-products"><small>{{ form.recommendationKicker || 'HOT PICKS' }}</small><h3>{{ form.recommendationTitle || '大家正在买' }}</h3><div><i v-for="n in Number(form.recommendationDisplayCount || 4)" :key="n" /></div></div></div>
        </section>
      </div>
    </template>
  </div>
</template>

<script>
import { addHomeContent, disableHomeContent, getHomeContent, listHomeContent, updateHomeContent } from '@/api/mall/homeContent'

function emptyForm () { return { contentId: undefined, contentType: 'HERO', contentName: '', status: 'DRAFT', effectiveTime: '', expireTime: undefined, sortNo: 0, heroEyebrow: 'NEW DROP', heroTitle: '', heroSubtitle: '', heroActionText: '开始逛逛', heroTargetType: 'INTERNAL', heroTargetValue: '/catalog', heroPrimaryImage: '/assets/sneaker.jpg', heroSecondaryImage: '/assets/headphones.jpg', heroNewItemCount: 8, tickerItems: [{ label: 'FREE SHIPPING', text: '满 199 元免运费' }], recommendationKicker: 'HOT PICKS', recommendationTitle: '大家正在买', recommendationTargetType: 'INTERNAL', recommendationTargetValue: '/catalog?sort=sales', recommendationDisplayCount: 4, recommendationFallbackMode: 'SALES', recommendationSpuIds: [] } }

export default {
  name: 'MallHomepageContent',
  data () { return { viewMode: 'list', previewOnly: false, previewDevice: 'desktop', loading: false, saving: false, rows: [], total: 0, recommendationInput: '', form: emptyForm(), query: { pageNum: 1, pageSize: 10, keyword: undefined, contentType: undefined, status: undefined }, contentTypes: [{ value: 'HERO', label: '主视觉' }, { value: 'TICKER', label: '公告条' }, { value: 'RECOMMENDATION', label: '推荐专区' }], rules: { contentType: [{ required: true, message: '请选择内容类型', trigger: 'change' }], contentName: [{ required: true, message: '请输入内容名称', trigger: 'blur' }], effectiveTime: [{ required: true, message: '请选择生效时间', trigger: 'change' }], heroTitle: [{ required: true, message: '请输入主标题', trigger: 'blur' }], heroPrimaryImage: [{ required: true, message: '请上传主图', trigger: 'change' }], heroSecondaryImage: [{ required: true, message: '请上传副图', trigger: 'change' }] } } },
  computed: { previewTickers () { return this.form.contentType === 'TICKER' && this.form.tickerItems.length ? this.form.tickerItems : [{ label: 'FREE SHIPPING', text: '满 199 元免运费' }, { label: 'NEW ARRIVALS', text: '每周二上新' }] } },
  created () { this.load() },
  methods: {
    load () { this.loading = true; listHomeContent(this.query).then(response => { this.rows = response.rows || []; this.total = response.total || 0 }).finally(() => { this.loading = false }) }, handleQuery () { this.query.pageNum = 1; this.load() }, resetQuery () { this.$refs.queryForm.resetFields(); this.handleQuery() },
    openCreate () { this.form = emptyForm(); this.recommendationInput = ''; this.previewOnly = false; this.viewMode = 'editor' }, openEditor (id, previewOnly) { getHomeContent(id).then(response => { this.form = Object.assign(emptyForm(), response.data || {}); this.form.tickerItems = this.form.tickerItems || [{ label: '', text: '' }]; this.recommendationInput = (this.form.recommendationSpuIds || []).join(','); this.previewOnly = previewOnly; this.viewMode = 'editor' }) }, backToList () { this.viewMode = 'list'; this.load() },
    addTicker () { if (this.form.tickerItems.length < 5) this.form.tickerItems.push({ label: '', text: '' }) }, removeTicker (index) { if (this.form.tickerItems.length > 1) this.form.tickerItems.splice(index, 1) },
    submit (status) { this.$refs.contentForm.validate(valid => { if (!valid) return; const data = Object.assign({}, this.form, { status, recommendationSpuIds: this.recommendationInput.split(',').map(value => Number(value.trim())).filter(value => Number.isInteger(value) && value > 0) }); this.saving = true; const req = data.contentId ? updateHomeContent(data) : addHomeContent(data); req.then(() => { this.$modal.msgSuccess(status === 'PUBLISHED' ? '发布排期成功' : '草稿保存成功'); this.backToList() }).finally(() => { this.saving = false }) }) },
    handleDisable (row) { this.$modal.confirm(`确认停用“${row.contentName}”吗？`).then(() => disableHomeContent(row.contentId)).then(() => { this.$modal.msgSuccess('停用成功'); this.load() }).catch(() => {}) }, typeLabel (value) { const item = this.contentTypes.find(row => row.value === value); return item ? item.label : value }, countStatus (value) { return this.rows.filter(row => row.runtimeStatus === value).length }, runtimeLabel (value) { return ({ DRAFT: '草稿', DISABLED: '已停用', SCHEDULED: '待生效', EXPIRED: '已过期', ONLINE: '线上' })[value] || value }, statusType (value) { return ({ ONLINE: 'success', SCHEDULED: 'warning', EXPIRED: 'info', DISABLED: 'info', DRAFT: '' })[value] || '' }, imageUrl (value) { const first = String(value || '').split(',')[0]; if (!first) return '/assets/sneaker.jpg'; if (/^https?:\/\//.test(first)) return first; if (first.startsWith('/assets/')) return `http://localhost:5174${first}`; return `${process.env.VUE_APP_BASE_API || ''}${first}` }
  }
}
</script>

<style scoped>
