}.editor-actions{display:flex;justify-content:flex-end;margin-top:20px;padding-top:18px;border-top:1px solid #e8edf2}.preview-panel{align-self:start;position:sticky;top:84px}.store-preview{margin:18px;padding:16px;overflow:hidden;border:1px solid #dfe5ed;background:#fff8e8}.preview-top{display:flex;justify-content:space-between;padding:5px 2px 13px;font-size:10px}.preview-hero{display:grid;grid-template-columns:1fr .9fr;min-height:230px;border:2px solid #20202a;background:#ffd0ba;box-shadow:5px 5px 0 #20202a}.preview-hero>div:first-child{display:flex;align-items:flex-start;justify-content:center;padding:28px;flex-direction:column}.preview-hero small,.preview-products>small{color:#d64f39;font-size:9px;font-weight:800;letter-spacing:.1em}.preview-hero h3{margin:10px 0;font-size:28px;line-height:1.16}.preview-hero p{margin:0 0 15px;color:#765d52;font-size:11px;line-height:1.6}.preview-hero button{border:2px solid #20202a;border-radius:5px;padding:7px 12px;background:#ffd946;box-shadow:3px 3px 0 #20202a;font-weight:700}.preview-collage{position:relative;min-height:200px}.preview-collage img{position:absolute;object-fit:cover;border:2px solid #20202a}.preview-collage img:first-child{right:12px;bottom:16px;width:72%;height:76%}.preview-collage img:nth-child(2){top:18px;left:2px;width:42%;height:42%}.preview-collage>b{position:absolute;right:4px;top:12px;padding:5px;background:#fff;font-size:10px}.preview-ticker{display:flex;gap:8px;overflow:hidden;margin:15px 0;padding:10px;border:2px solid #20202a;background:#fff;white-space:nowrap}.preview-ticker span{color:#d64f39;font-size:8px;font-weight:800}.preview-ticker b{font-size:9px}.preview-products{padding:10px 2px}.preview-products h3{margin:6px 0 12px;font-size:20px}.preview-products>div{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.preview-products i{display:block;aspect-ratio:1;border:2px solid #20202a;background:#dcece2}.preview-products i:nth-child(2n){background:#f5c9b4}.store-preview.mobile{max-width:390px;margin:18px auto}.store-preview.mobile .preview-top span{display:none}.store-preview.mobile .preview-hero{grid-template-columns:1fr}.store-preview.mobile .preview-collage{min-height:190px}.store-preview.mobile .preview-products>div{grid-template-columns:repeat(2,1fr)}@media(max-width:1100px){.workspace-grid{grid-template-columns:1fr}.preview-panel{position:static;order:-1}}@media(max-width:760px){.page-heading{align-items:stretch;flex-direction:column}.summary-band{grid-template-columns:repeat(2,1fr)}.workspace-grid{display:block}.preview-panel{margin-bottom:14px}.form-row,.ticker-row{grid-template-columns:1fr}.editor-panel .el-form{padding:14px}.store-preview{margin:12px;padding:10px}.preview-hero{grid-template-columns:1fr}.preview-collage{min-height:190px}}
</style>
